sig
  type rusage = {
    maxrss : int64;
    minflt : int64;
    majflt : int64;
    inblock : int64;
    oublock : int64;
    nvcsw : int64;
    nivcsw : int64;
  }
  type ocaml_gc = {
    minor_words : float;
    promoted_words : float;
    major_words : float;
    minor_collections : int;
    major_collections : int;
    heap_words : int;
    compactions : int;
    top_heap_words : int;
    stack_size : int;
  }
  type duration = { wall : float; sys : float; user : float; }
  type step = {
    duration : duration;
    rusage : rusage;
    ocaml_gc : ocaml_gc;
    index : 'a;
    pack_store : Pack_store/2.t;
    inode : 'b;
  }
  type worker = {
    initial_maxrss : int64;
    initial_heap_words : int;
    initial_top_heap_words : int;
    initial_stack_size : int;
    steps : (string * step) list;
    files : (string * 'a) list;
    objects_traversed : 'b;
    suffix_transfers : 'c list;
  }
  type stats = {
    generation : int;
    commit_offset : 'a;
    before_suffix_start_offset : 'b;
    before_suffix_end_offset : 'c;
    after_suffix_start_offset : 'd;
    after_suffix_end_offset : 'e;
    steps : (string * duration) list;
    worker : worker;
  }
  type t = stats option
end

sig
  module Pack_store :
    sig
      type field =
          Appended_hashes
        | Appended_offsets
        | Staging
        | Lru
        | Pack_direct
        | Pack_indexed
        | Not_found
      type t =
        Pack_store.t = {
        mutable appended_hashes : int;
        mutable appended_offsets : int;
        mutable total : int;
        mutable from_staging : int;
        mutable from_lru : int;
        mutable from_pack_direct : int;
        mutable from_pack_indexed : int;
      }
      type stat
      val cache_misses : t -> int
      val export : stat -> t
    end
  module Index : sig type stat val export : stat -> 'a end
  module File_manager :
    sig
      type field =
          Dict_flushes
        | Suffix_flushes
        | Index_flushes
        | Auto_dict
        | Auto_suffix
        | Auto_index
        | Flush
      type t =
        File_manager.t = {
        mutable dict_flushes : int;
        mutable suffix_flushes : int;
        mutable index_flushes : int;
        mutable auto_dict : int;
        mutable auto_suffix : int;
        mutable auto_index : int;
        mutable flush : int;
      }
      type stat
      val export : stat -> t
    end
  module Latest_gc :
    sig
      type stat
      val export : stat -> 'a
      val new_suffix_end_offset_before_finalise : 'a -> 'b
      val finalise_duration : 'a -> float
      val total_duration : 'a -> float
      val finalise_suffix_transfer : 'a -> 'b
    end
  type t = {
    pack_store : Pack_store.stat;
    index : Index.stat;
    file_manager : File_manager.stat;
    latest_gc : Latest_gc.stat;
  }
  val reset_stats : unit -> unit
  val get : unit -> t
  val report_pack_store : field:Pack_store.field -> unit
  val report_index : unit -> unit
  val incr_appended_hashes : unit -> unit
  val incr_appended_offsets : unit -> unit
  type cache_stats = { cache_misses : float; }
  type offset_stats = { offset_ratio : float; offset_significance : int; }
  val get_cache_stats : unit -> cache_stats
  val get_offset_stats : unit -> offset_stats
  val incr_fm_field : File_manager.field -> unit
  val report_latest_gc : 'a -> unit
end

