type t = {
  w : 'a;
  r : 'b;
  mutable state : state;
  mutable last_refresh : float;
  mutable current : counter;
  max : counter;
  f : 'c;
}

type t = {
  mutable buf : 'a;
  mutable off : int;
  mutable len : int;
  waiters : 'b;
}

value:
match let new_len = ref old_len in
      let space = writable_space t in
      while ((space + (!new_len)) - old_len) < to_copy do
        new_len := ((3 * (!new_len)) / 2) done;
      (let new_buf = ( *type-error* ) (!new_len) in
       ( *type-error* ) t.buf ~src_off:(t.off) new_buf ~dst_off:0
         ~len:(t.len - t.off);
       t.buf <- new_buf;
       t.len <- (t.len - t.off);
       t.off <- 0)
with
| () -> _
